-- Create upazilas table
CREATE TABLE IF NOT EXISTS public.upazilas (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  division text NOT NULL,
  district text NOT NULL,
  upazila text NOT NULL,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (division, district, upazila)
);

GRANT SELECT ON public.upazilas TO anon, authenticated;
GRANT ALL ON public.upazilas TO service_role;

ALTER TABLE public.upazilas ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Anyone can read upazilas" ON public.upazilas;
CREATE POLICY "Anyone can read upazilas" ON public.upazilas FOR SELECT USING (true);

CREATE INDEX IF NOT EXISTS idx_upazilas_div_dist ON public.upazilas (division, district);

-- Add division / upazila to agents
ALTER TABLE public.agents
  ADD COLUMN IF NOT EXISTS division text,
  ADD COLUMN IF NOT EXISTS upazila text;

ON CONFLICT (division, district, upazila) DO NOTHING;